var primerDigito = n => {
  if (n%1!==0) throw "El número debe ser entero";
  let m =Math.abs(n);
  let d =1;
  while (m/d>=10) d*=10;
  return Math.quot(n,d);
};

var invertirDigitos = function(n) {
  if (n%1!==0) throw "El número debe ser entero";
  let ni =0 ;
  while (n<0||n>0) {
    ni =ni*10+n%10;
    n =Math.quot(n,10);
  }
  return ni;
};

var raizCuadrada = function(n, x2=1.1) {
  if (n<0) throw "El número debe ser positivo";
  if (n==0 || n==1) return n;
  let x1;
  do {
    x1 = x2;
    x2 = (x1+n/x1)/2;
  } while(Math.abs(x1/x2-1)>=1e-10);
  return x2;
};

function raizCubica(n,x2=1.1) {if (n==0||n==1) return n;
  let x1;
  do {
    x1 =x2;
    x2 =(2*x1+n/x1**2)/3;
  } while(Math.abs(x1/x2-1)>=1e-11);
  return x2 ;
};

