var fibonacci = function(n) {
  if (n%1!==0) throw "El número debe ser entero";
  if (n<=0) throw "El número debe ser mayor a cero";
  if (n<3) return 1;
  let f1=1, f2=1, f3;
  for(let i=3;i<n+1; i++){
    f3 =f2+f1 ;
    f1=f2;
    f2=f3;
  }
  return f3 ;
};

var chebyshev = (x, n) => {
  if (n%1!==0) throw "El orden debe ser entero";
  if (n<0) throw "El orden debe ser positivo";
  if (n===0) return 1;
  if (n===1) return x;
  let ch0=1, ch1=x, ch2;
  for(let i=2;i<=n;i++){
    ch2 =2*x*ch1-ch0 ;
    ch0=ch1;
    ch1=ch2;
  }
  return  ch2;
};

function laguerre(x, n) {
  if (n%1!==0) throw "El orden debe ser entero";
  if (n<0) throw "El orden debe ser positivo";
  if (n==0) return 1;
  if (n==1) return 1-x ;
  let la0=1, la1=1-x, la2;
  for(let i=2;i<=n;i++){
    la2 =((2*i-1-x)*la1-(i-1)*la0)/i ;
    la0=la1;
    la1=la2;
  }
  return la2 ;
};
